private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    // Assume: bb is a heap ByteBuffer with an array and an arrayOffset
    // We will decode bytes from position i onwards in the byte array
    int limit = bb.limit();
    int offset = bb.arrayOffset();
    byte[] array = bb.array();

    // Start from position i
    while (i < limit) {
        int b = array[offset + i] & 0xFF;

        if (b < 0x80) {
            // 1-byte character
            sb.append((char) b);
            i++;
        } else if ((b >> 5) == 0x6) {
            // 2-byte character
            if (i + 1 < limit) {
                int b2 = array[offset + i + 1] & 0xFF;
                if ((b2 >> 6) == 0x2) {
                    int codePoint = ((b & 0x1F) << 6) | (b2 & 0x3F);
                    sb.append((char) codePoint);
                    i += 2;
                } else {
                    // Invalid continuation byte, return to allow caller to handle
                    return i;
                }
            } else {
                // Not enough bytes for a 2-byte character
                return i;
            }
        } else if ((b >> 4) == 0xE) {
            // 3-byte character
            if (i + 2 < limit) {
                int b2 = array[offset + i + 1] & 0xFF;
                int b3 = array[offset + i + 2] & 0xFF;
                if ((b2 >> 6) == 0x2 && (b3 >> 6) == 0x2) {
                    int codePoint = ((b & 0x0F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
                    // Surrogate check for supplementary characters
                    if (codePoint > 0xFFFF && codePoint < 0x10000) {
                        throw new IllegalArgumentException("Surrogate character detected: " + codePoint);
                    }
                    if (codePoint >= 0x10000) {
                        // Convert to surrogates
                        int v = codePoint - 0x10000;
                        sb.append((char) (0xD800 | (v >> 10)));
                        sb.append((char) (0xDC00 | (v & 0x3FF)));
                    } else {
                        sb.append((char) codePoint);
                    }
                    i += 3;
                } else {
                    // Invalid continuation bytes, return to allow caller to handle
                    return i;
                }
            } else {
                // Not enough bytes for a 3-byte character
                return i;
            }
        } else if ((b >> 3) == 0x1E) {
            // 4-byte character
            if (i + 3 < limit) {
                int b2 = array[offset + i + 1] & 0xFF;
                int b3 = array[offset + i + 2] & 0xFF;
                int b4 = array[offset + i + 3] & 0xFF;
                if ((b2 >> 6) == 0x2 && (b3 >> 6) == 0x2 && (b4 >> 6) == 0x2) {
                    int codePoint = ((b & 0x07) << 18) | ((b2 & 0x3F) << 12) | ((b3 & 0x3F) << 6) | (b4 & 0x3F);
                    // Surrogate check for supplementary characters
                    if (codePoint < 0x10000 || codePoint > 0x10FFFF) {
                        throw new IllegalArgumentException("Invalid code point: " + codePoint);
                    }
                    if (codePoint >= 0x10000) {
                        // Convert to surrogates
                        int v = codePoint - 0x10000;
                        sb.append((char) (0xD800 | (v >> 10)));
                        sb.append((char) (0xDC00 | (v & 0x3FF)));
                    } else {
                        sb.append((char) codePoint);
                    }
                    i += 4;
                } else {
                    // Invalid continuation bytes, return to allow caller to handle
                    return i;
                }
            } else {
                // Not enough bytes for a 4-byte character
                return i;
            }
        } else {
            // Invalid leading byte, return to allow caller to handle
            return i;
        }
    }

    return i;
}
