private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int length = bb.remaining();
    if (length == 0) {
        return i;
    }
    int ch;
    int p = bb.position();
    if ((bb.get(p) & 0xe0) == 0xc0 && (length >= 2)) {
        ch = ((bb.get(p) & 0x1f) << 6) | (bb.get(p + 1) & 0x3f);
        bb.position(p + 2);
        sb.append((char) ch);
        return i + 1;
    } else if ((bb.get(p) & 0xf0) == 0xe0 && (length >= 3)) {
        ch = ((bb.get(p) & 0x0f) << 12) | ((bb.get(p + 1) & 0x3f) << 6) | (bb.get(p + 2) & 0x3f);
        bb.position(p + 3);
        sb.append((char) ch);
        return i + 1;
    } else if ((bb.get(p) & 0xf8) == 0xf0 && (length >= 4)) {
        int cp = ((bb.get(p) & 0x07) << 18) | ((bb.get(p + 1) & 0x3f) << 12)
                | ((bb.get(p + 2) & 0x3f) << 6) | (bb.get(p + 3) & 0x3f);
        bb.position(p + 4);
        int lo = cp - 0x10000;
        sb.append((char) (0xd800 + (lo >> 10)));
        sb.append((char) (0xdc00 + (lo & 0x3ff)));
        return i + 1;
    } else {
        ch = bb.get(p) & 0x7f;
        bb.position(p + 1);
        sb.append((char) ch);
        return i + 1;
    }
