    private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
        while (i < bb.limit()) {
            byte b = bb.get(i);
            if (b >= 0) {
                sb.append((char) b);
                i++;
            } else if ((b & 0xE0) == 0xC0) {
                if (i + 1 >= bb.limit()) break;
                byte b1 = bb.get(i + 1);
                if ((b1 & 0xC0) != 0x80) {
                    sb.append('?');
                    i++;
                } else {
                    char c = (char) (((b & 0x1F) << 6) | (b1 & 0x3F));
                    sb.append(c);
                    i += 2;
                }
            } else if ((b & 0xF0) == 0xE0) {
                if (i + 2 >= bb.limit()) break;
                byte b1 = bb.get(i + 1);
                byte b2 = bb.get(i + 2);
                if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80) {
                    sb.append('?');
                    i++;
                } else {
                    int codePoint = ((b & 0x0F) << 12) | ((b1 & 0x3F) << 6) | (b2 & 0x3F);
                    if (codePoint >= 0x10000) {
                        codePoint -= 0x10000;
                        sb.append((char) (0xD800 + (codePoint >>> 10)));
                        sb.append((char) (0xDC00 + (codePoint & 0x3FF)));
                    } else {
                        sb.append((char) codePoint);
                    }
                    i += 3;
                }
            } else if ((b & 0xF8) == 0xF0) {
                if (i + 3 >= bb.limit()) break;
                byte b1 = bb.get(i + 1);
                byte b2 = bb.get(i + 2);
                byte b3 = bb.get(i + 3);
                if ((b1 & 0xC0) != 0x80 || (b2 & 0xC0) != 0x80 || (b3 & 0xC0) != 0x80) {
                    sb.append('?');
                    i++;
                } else {
                    int codePoint = ((b & 0x07) << 18) | ((b1 & 0x3F) << 12) | ((b2 & 0x3F) << 6) | (b3 & 0x3F);
                    if (codePoint < 0x10000 || codePoint > 0x10FFFF) {
                        sb.append('?');
                    } else {
                        codePoint -= 0x10000;
                        sb.append((char) (0xD800 + (codePoint >>> 10)));
                        sb.append((char) (0xDC00 + (codePoint & 0x3FF)));
                    }
                    i += 4;
                }
            } else {
                sb.append('?');
                i++;
            }
        }
        return i;
    }
