    private void enlarge(final int size) {
        if (size <= 0) {
            return;
        }
        final int oldLength = this.bytes.length;
        int newLength;
        if (size > (Integer.MAX_VALUE - oldLength)) {
            throw new OutOfMemoryError("Byte vector count is too big");
        }
        newLength = oldLength + size;

        final byte[] newBytes = new byte[newLength];
        System.arraycopy(this.bytes, 0, newBytes, 0, oldLength);
