    /**
     * Construct a complete bipartite graph
     */
    @Override 
    public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
        int totalVertices = getVertexCount();
        if (totalVertices < 2) {
            throw new IllegalArgumentException("A complete bipartite graph requires at least 2 vertices.");
        }

        int partASize = getPartASize();
        int partBSize = getPartBSize();

        if (partASize <= 0 || partBSize <= 0) {
            throw new IllegalArgumentException("Both parts of the complete bipartite graph must have at least one vertex.");
        }

        if (partASize + partBSize != totalVertices) {
            throw new IllegalArgumentException("The sum of part sizes must equal the total number of vertices.");
        }

        // Generate vertices for part A
        for (int i = 0; i < partASize; i++) {
            String key = "A" + i;
            V vertexA = newVertex(key);
            target.addVertex(vertexA);
            resultMap.put(key, vertexA);
        }

        // Generate vertices for part B
        for (int i = 0; i < partBSize; i++) {
            String key = "B" + i;
            V vertexB = newVertex(key);
            target.addVertex(vertexB);
            resultMap.put(key, vertexB);
        }

        // Create complete bipartite connections
        for (int i = 0; i < partASize; i++) {
            V vertexA = resultMap.get("A" + i);
            for (int j = 0; j < partBSize; j++) {
                V vertexB = resultMap.get("B" + j);
                E edge = newEdge(vertexA, vertexB);
                target.addEdge(vertexA, vertexB, edge);
            }
        }
    }
