    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        // Complete bipartite graph K(m,n)
        // m and n are the sizes of the two partitions
        int m = 3;
        int n = 3;

        // Calculate total number of vertices
        int totalVertices = m + n;

        // Build the graph
        // Points with indices 0..m-1 belong to partition A
        // Points with indices m..totalVertices-1 belong to partition B
        List<String> pointNames = new ArrayList<String>();
        int pointIndex = 0;

        for (int i = 0; i < totalVertices; i++) {
            String name = "P" + (pointIndex++);
            pointNames.add(name);
            resultMap.put(name, target.addVertex(name));
        }

        // Add edges between every node in partition A and every node in partition B
        for (int i = 0; i < m; i++) {
            String aName = pointNames.get(i);
            for (int j = m; j < totalVertices; j++) {
                String bName = pointNames.get(j);
                target.addEdge(resultMap.get(aName), resultMap.get(bName));
            }
        }
    }
