public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null;
    }

    Map<String, Object> currentMappings = getCurrentMappings(tableName);
    if (currentMappings == null) {
        return new Mappings(mappings.getFields());
    }

    // Extract field names from input mappings (history mappings)
    Set<String> inputFieldNames = new HashSet<>();
    if (mappings.getFields() != null) {
        for (Field field : mappings.getFields().values()) {
            inputFieldNames.add(field.getName());
        }
    }

    // Extract field names from current mappings
    Set<String> currentFieldNames = new HashSet<>();
    if (currentMappings.containsKey("properties")) {
        @SuppressWarnings("unchecked")
        Map<String, Object> properties = (Map<String, Object>) currentMappings.get("properties");
        if (properties != null) {
            currentFieldNames.addAll(properties.keySet());
        }
    }

    // Find fields that exist in current mappings but not in input mappings
    Set<String> newFieldNames = new HashSet<>(currentFieldNames);
    newFieldNames.removeAll(inputFieldNames);

    // Build result mappings with only the new fields
    Map<String, Field> resultFields = new HashMap<>();
    for (String fieldName : newFieldNames) {
        Field field = mappings.getField(fieldName);
        if (field != null) {
            resultFields.put(fieldName, field);
        }
    }

    if (resultFields.isEmpty()) {
        return new Mappings();
    }

    // Exclude _source configuration to avoid current index update conflict
    Map<String, Object> resultJson = new HashMap<>();
    resultJson.put("properties", resultFields);

    Mappings result = new Mappings(resultFields);
    // Ensure _source is not included
    result.setSource(null);

    return result;
}

