        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            daysInMonth = 29;
        } else {
            daysInMonth = 28;
        }
    }

    // Clamp day to valid range
    if (day > daysInMonth) {
        day = daysInMonth;
    }

    long baseOfYear = year * 10000 + month * 100 + 1;
    long diffFromStart = day - 1;
    long bucketIndex = diffFromStart / dayStep;
    long adjustedDay = bucketIndex * dayStep + 1;

