    public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
        if (str != null) {
            // Calculate the encoded length
            int encodedLength = 0;
            int strLength = str.length();
            for (int i = 0; i < strLength; i++) {
                char c = str.charAt(i);
                if (c <= 0x7F) {
                    encodedLength += 1;
                } else if (c <= 0x7FF) {
                    encodedLength += 2;
                } else if (c <= 0xFFFF) {
                    encodedLength += 3;
                } else {
                    encodedLength += 4;
                }
            }

            // Ensure we have enough space
            lb.init(session, encodedLength, false);

            int offset = lb.offset();
            byte[] buffer = lb.allocate(offset, encodedLength);

            int encodedIndex = 0;
            for (int i = 0; i < strLength; i++) {
                char c = str.charAt(i);
                if (c <= 0x7F) {
                    buffer[encodedIndex++] = (byte) c;
                } else if (c <= 0x7FF) {
                    buffer[encodedIndex++] = (byte) (0xC0 | (c >> 6));
                    buffer[encodedIndex++] = (byte) (0x80 | (c & 0x3F));
                } else if (c <= 0xFFFF) {
                    buffer[encodedIndex++] = (byte) (0xE0 | (c >> 12));
                    buffer[encodedIndex++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                    buffer[encodedIndex++] = (byte) (0x80 | (c & 0x3F));
                } else {
                    buffer[encodedIndex++] = (byte) (0xF0 | (c >> 18));
                    buffer[encodedIndex++] = (byte) (0x80 | ((c >> 12) & 0x3F));
                    buffer[encodedIndex++] = (byte) (0x80 | ((c >> 6) & 0x3F));
                    buffer[encodedIndex++] = (byte) (0x80 | (c & 0x3F));
                }
            }

            lb.addBytes(buffer, encodedIndex);
        }
        return lb;
    }
