public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform simple variable substitution: replace ${var} patterns with properties
    StringBuilder result = new StringBuilder(value);
    boolean found;
    do {
        found = false;
        int startIndex = result.indexOf("${");
        if (startIndex >= 0) {
            int endIndex = result.indexOf('}', startIndex);
            if (endIndex > startIndex) {
                String nestedKey = result.substring(startIndex + 2, endIndex);
                String replacement = props.getProperty(nestedKey);
                if (replacement != null) {
                    replacement = findAndSubst(nestedKey, props);
                } else {
                    replacement = "";
                }
                result.replace(startIndex, endIndex + 1, replacement);
                found = true;
            }
        }
    } while (found);
    return result.toString();
}
