public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution: handle ${var} patterns
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        if (i < value.length() - 2 && value.charAt(i) == '$' && value.charAt(i + 1) == '{') {
            int end = value.indexOf('}', i + 2);
            if (end != -1) {
                String varName = value.substring(i + 2, end);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    sb.append(varValue);
                } else {
                    sb.append(value, i, end + 1); // leave as is if not found
                }
                i = end + 1;
            } else {
                sb.append(value, i, value.length());
                i = value.length();
            }
        } else {
            sb.append(value.charAt(i));
            i++;
        }
    }
    return sb.toString();
}
