    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<PathSegmentImpl>();
        if (u == null) {
            return pathSegments;
        }
        String path = u.getRawPath();
        if (path == null) {
            return pathSegments;
        }
        // Check if it's an absolute path component
        boolean isAbsolute = path.startsWith("/");
        if (isAbsolute) {
            path = path.substring(1); // ignore leading '/'
        }
        if (path.isEmpty()) {
            return pathSegments;
        }
        // Split the path by '/'
        String[] segments = path.split("/", -1);
        for (String segment : segments) {
            if (segment.isEmpty()) {
                continue;
            }
            if (decode) {
                segment = decodeSegment(segment);
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
        return pathSegments;
    }

    private static String decodeSegment(String segment) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < segment.length()) {
            char c = segment.charAt(i);
            if (c == '%' && i + 2 < segment.length()) {
                String hex = segment.substring(i + 1, i + 3);
                try {
                    int codePoint = Integer.parseInt(hex, 16);
                    sb.append((char) codePoint);
                    i += 3;
                } catch (NumberFormatException e) {
                    sb.append(c);
                    i++;
                }
            } else {
                sb.append(c);
                i++;
            }
        }
        return sb.toString();
    }
