public Converter lookup(final Class<?> clazz) {
    // Check if the class is null
    if (clazz == null) {
        return null;
    }

    // Iterate through registered converters and check if any matches the target class
    for (Converter converter : converters) {
        Class<?> targetClass = converter.getTargetClass();
        if (targetClass != null && targetClass.isAssignableFrom(clazz)) {
            return converter;
        }
    }

    // Return null if no matching converter is found
    return null;
}
