private void pop(final String descriptor) {
        // Determine the number of types to pop based on the descriptor
        int typesToPop = 0;
        // Check if the descriptor represents a method descriptor
        if (descriptor.startsWith("(")) {
            // For method descriptors, count the parameter types
            int index = 1; // Skip the opening parenthesis
            while (index < descriptor.length()) {
                typesToPop++;
                index = skipType(descriptor, index);
                // Check if we've reached the end of the parameter list
                if (index < descriptor.length() && descriptor.charAt(index) == ')') {
                    break;
                }
            }
        } else {
            // For a single type descriptor
            typesToPop = 1;
        }

        // Pop the determined number of types from the output frame stack
        for (int i = 0; i < typesToPop; i++) {
            // Pop each type from the output frame stack
            outputFrame.outStack().pop();
        }
    }

private void pop(final String descriptor) {
    if (descriptor.charAt(0) == '(') {
        int index = descriptor.indexOf(')');
        for (int i = 1; i < index; ++i) {
            if (descriptor.charAt(i) == '[') {
                continue;
            }
            popType(descriptor.charAt(i));
        }
        popType(descriptor.charAt(index + 1));
    } else {
        popType(descriptor.charAt(0));
    }
