private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    char first = descriptor.charAt(0);
    if (first == '(') {
        // Method descriptor: skip '(' and pop argument types
        int depth = 1;
        int i = 1;
        while (i < descriptor.length() && depth > 0) {
            char c = descriptor.charAt(i);
            if (c == '(') {
                depth++;
            } else if (c == ')') {
                depth--;
            } else if (c == '[' || isTypeNameStart(c)) {
                // Skip the type descriptor
                i = skipTypeDescriptor(descriptor, i);
                // Pop the type onto the output frame
                // Assuming there is a method to pop type from output frame
                popType();
                continue;
            }
            i++;
        }
    } else {
        // Single type descriptor
        i = 0;
        while (i < descriptor.length()) {
            if (descriptor.charAt(i) == '[') {
                i++;
            } else {
                popType();
                i = skipTypeDescriptor(descriptor, i);
            }
        }
    }
}

private void pop(final String descriptor) {
    if (descriptor.charAt(0) == ')') {
        // Method descriptor: find the corresponding '(' and pop each argument
        int openIndex = descriptor.indexOf('(');
        String args = descriptor.substring(openIndex + 1, descriptor.indexOf(')'));
        int i = 0;
        while (i < args.length()) {
            char c = args.charAt(i);
            if (c == '[') {
                // Skip array dimensions
            } else {
                int startIndex = i;
                while (i < args.length() && Character.isLetter(args.charAt(i))) {
                    i++;
                }
                String typeStr = args.substring(startIndex, i);
                pop(typeStr);
                continue;
            }
            i++;
        }
    } else {
        // Simple or array type
        int i = 0;
        // Skip array dimensions
        while (i < descriptor.length() && descriptor.charAt(i) == '[') {
            i++;
        }
        if (i < descriptor.length()) {
            char typeChar = descriptor.charAt(i);
            if (typeChar == 'L') {
                // Reference type: pop the class name
                int semicolon = descriptor.indexOf(';');
                // For this operation, we just need to pop an entry, so pop one
                outputFrame.pop();
            } else {
                // Primitive type: pop one entry
                outputFrame.pop();
            }
        }
    }
}

