    if (count + len > buf.length) {
        if (len > buf.length) {
            System.arraycopy(b, off, buf, 0, buf.length);
            off += buf.length;
            len -= buf.length;
            count = buf.length;
            flushBuffer();
        } else {
            throw new IOException("Buffer overflow: " + count + " + " + len + " exceeds " + buf.length);
        }
