public void readFrom(final InputStream in) throws IOException {
    int nBytes = (in.available() <= 0) ? DEFAULT_BUFFER_SIZE : in.available();
    if (in.available() <= 0) {
        nBytes = DEFAULT_BUFFER_SIZE;
    }
    byte[] buffer = new byte[nBytes];
    int totalRead = 0;
    int bytesRead;
    while ((bytesRead = in.read(buffer, totalRead, buffer.length - totalRead)) != -1) {
        totalRead += bytesRead;
        if (totalRead == buffer.length) {
            // buffer full, check if more data
            break;
        }
    }
    // If buffer is full, read remaining data into a larger buffer
    if (totalRead == buffer.length) {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        baos.write(buffer, 0, buffer.length);
        bytesRead;
        while ((bytesRead = in.read(buffer, 0, buffer.length)) != -1) {
            baos.write(buffer, 0, bytesRead);
        }
        buffer = baos.toByteArray();
    }
    this.buffer = buffer;
    this.position = 0;
    this.limit = buffer.length;
}
