public String readString() throws IOException {
    byte b;
    do {
        b = read();
        if (b == -1) {
            throw new EOFException("Unterminated string");
        }
    } while (b == 0);
    StringBuilder sb = new StringBuilder();
    while (b != -1 && b != 0) {
        sb.append((char) b);
        b = read();
    }
    if (b == -1) {
        throw new EOFException("Unterminated string");
    }
    return sb.toString();
}
