private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement valueElement = entry.getValue();
        if (valueElement.isJsonNull()) {
            content.put(key, null);
        } else if (valueElement.isJsonPrimitive()) {
            JsonPrimitive value = valueElement.getAsJsonPrimitive();
            if (value.isString()) {
                content.put(key, value.getAsString());
            } else if (value.isNumber()) {
                content.put(key, value.getAsNumber());
            } else if (value.isBoolean()) {
                content.put(key, value.getAsBoolean());
            }
        } else if (valueElement.isJsonObject()) {
            content.put(key, buildContentAsMap(valueElement.getAsJsonObject()));
        } else if (valueElement.isJsonArray()) {
            content.put(key, buildContentAsList(valueElement.getAsJsonArray()));
        }
    }
    return content;
}

private Map<String,Object> buildContentAsMap(JsonObject jsonObject) {
    return buildContent(jsonObject);
}

private List<Object> buildContentAsList(JsonArray jsonArray) {
    List<Object> list = new ArrayList<>();
    for (JsonElement element : jsonArray) {
        if (element.isJsonNull()) {
            list.add(null);
        } else if (element.isJsonPrimitive()) {
            JsonPrimitive value = element.getAsJsonPrimitive();
            if (value.isString()) {
                list.add(value.getAsString());
            } else if (value.isNumber()) {
                list.add(value.getAsNumber());
            } else if (value.isBoolean()) {
                list.add(value.getAsBoolean());
            }
        } else if (element.isJsonObject()) {
            list.add(buildContentAsMap(element.getAsJsonObject()));
        } else if (element.isJsonArray()) {
            list.add(buildContentAsList(element.getAsJsonArray()));
        }
    }
    return list;
}
