public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    if (str.indexOf('\\') == -1) {
        return str;
    }
    final int len = str.length();
    final StringBuilder buf = new StringBuilder(len);
    int unknown = buf.length();
    int i = 0;
    while (i < len) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i == (len - 1)) {
                buf.append(c);
                i++;
                continue;
            }
            final char next = str.charAt(i + 1);
            if (next == 'u') {
                if (i >= len - 4) {
                    appendUnicodeEscapeChar(buf, str, i);
                } else {
                    // check for malformed escape sequence
                    boolean malformed = false;
                    for (int j = i + 2; j <= i + 4; j++) {
                        char ch = str.charAt(j);
                        boolean isHex = (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
                        if (!isHex) {
                            malformed = true;
                            break;
                        }
                    }
                    if (malformed) {
                        appendUnknownEscapeChar(buf, c);
                        i++;
                    } else {
                        appendUnicodeEscapeChar(buf, str, i);
                    }
                }
            } else {
                switch (next) {
                    case 'b':
                        buf.append('\b');
                        break;
                    case 's':
                        buf.append(' ');
                        break;
                    case 't':
                        buf.append('\t');
                        break;
                    case 'n':
                        buf.append('\n');
                        break;
                    case 'f':
                        buf.append('\f');
                        break;
                    case 'a':
                        buf.append((char) 0x07);
                        break;
                    case 'r':
                        buf.append('\r');
                        break;
                    case '\\':
                        buf.append('\\');
                        break;
                    case '\"':
                        buf.append('\"');
                        break;
                    case '\'':
                        buf.append('\'');
                        break;
                    default:
                        if (i < unknown) {
                            unknown = buf.length();
                        }
                        break;
                }
                i += 2;
            }
        } else {
            buf.append(c);
            i++;
        }
    }
    return buf.toString();
}

private static void appendUnicodeEscapeChar(StringBuilder buf, String str, int i) throws Exception {
    buf.append(Character.toChars(Integer.parseInt(str.substring(i + 2, i + 6), 16)));
    i += 5;
}

private static void appendUnknownEscapeChar(StringBuilder buf, char c) {
    buf.append(c);
}
