public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    int len = str.length();
    if (len == 0) {
        return str;
    }

    StringBuilder buf = new StringBuilder(len);
    int i = 0;

    while (i < len) {
        char c = str.charAt(i);

        if (c == '\\') {
            if (i + 1 >= len) {
                throw new Exception("Unterminated escape sequence at end of string");
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'n':
                    buf.append('\n');
                    i += 2;
                    break;
                case 't':
                    buf.append('\t');
                    i += 2;
                    break;
                case 'r':
                    buf.append('\r');
                    i += 2;
                    break;
                case 'b':
                    buf.append('\b');
                    i += 2;
                    break;
                case 'f':
                    buf.append('\f');
                    i += 2;
                    break;
                case 'u':
                    if (i + 5 >= len) {
                        throw new Exception("Invalid unicode escape sequence");
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        buf.append((char) codePoint);
                        i += 6;
                    } catch (NumberFormatException e) {
                        throw new Exception("Invalid unicode escape sequence: " + hex);
                    }
                    break;
                case '\\':
                    buf.append('\\');
                    i += 2;
                    break;
                case '\'':
                    buf.append('\'');
                    i += 2;
                    break;
                case '"':
                    buf.append('"');
                    i += 2;
                    break;
                default:
                    buf.append(c);
                    buf.append(next);
                    i += 2;
                    break;
            }
        } else {
            buf.append(c);
            i++;
        }
    }

    return buf.toString();
}
