protected int removeUnusedNodes() {
    if (node == null) {
        return 0;
    }
    int removed = 0;
    int[] children = new int[node.getChildCount()];
    int kept = 0;
    for (int i = 0; i < node.getChildCount(); i++) {
        int childNode = node.getChild(i);
        int childRemoved = removeUnusedNodesOnNode(childNode);
        if (childRemoved > 0 || !isUnusedNode(childNode)) {
            children[kept++] = childNode;
        } else {
            node.remove(childNode);
            removed += childRemoved + 1;
        }
    }
    // Rebuild children list
    int originalCount = node.getChildCount();
    for (int i = originalCount - 1; i >= kept; i--) {
        node.remove(i);
    }
    for (int i = 0; i < kept; i++) {
        node.addChild(children[i]);
    }
    if (!isUnusedNode(node)) {
        return removed;
    } else {
        return removed + 1;
    }
}
