    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        // Read the length of the UTF-8 encoded string
        int length = readUnsignedShort();

        // Read the bytes of the UTF-8 encoded string
        byte[] bytes = new byte[length];
        for (int i = 0; i < length; i++) {
            bytes[i] = classFileBuffer.readByte();
        }

        // Convert the UTF-8 bytes to a character array
        int charIndex = 0;
        int byteIndex = 0;
        while (byteIndex < length) {
            int b1 = bytes[byteIndex] & 0xff;
            int codePoint;
            int numBytes;

            if (b1 < 0x80) {
                codePoint = b1;
                numBytes = 1;
            } else if ((b1 & 0xe0) == 0xc0) {
                if (byteIndex + 1 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding: truncated multi-byte sequence");
                }
                int b2 = bytes[byteIndex + 1] & 0x3f;
                codePoint = ((b1 & 0x1f) << 6) | b2;
                numBytes = 2;
            } else if ((b1 & 0xf0) == 0xe0) {
                if (byteIndex + 2 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding: truncated multi-byte sequence");
                }
                int b2 = bytes[byteIndex + 1] & 0x3f;
                int b3 = bytes[byteIndex + 2] & 0x3f;
                codePoint = ((b1 & 0x0f) << 12) | (b2 << 6) | b3;
                numBytes = 3;
            } else if ((b1 & 0xf8) == 0xf0) {
                if (byteIndex + 3 >= length) {
                    throw new IllegalArgumentException("Invalid UTF-8 encoding: truncated multi-byte sequence");
                }
                int b2 = bytes[byteIndex + 1] & 0x3f;
                int b3 = bytes[byteIndex + 2] & 0x3f;
                int b4 = bytes[byteIndex + 3] & 0x3f;
                codePoint = ((b1 & 0x07) << 18) | (b2 << 12) | (b3 << 6) | b4;
                numBytes = 4;
            } else if ((b1 & 0xfc) == 0xfe) {
                throw new IllegalArgumentException("Invalid UTF-8 encoding: unsupported byte sequence");
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 encoding: unsupported byte sequence");
            }

            // Handle surrogates for code points > 0xFFFF
            if (codePoint <= 0xFFFF) {
                charBuffer[charIndex++] = (char) codePoint;
            } else if (codePoint >= 0x10000 && codePoint <= 0x10FFFF) {
                codePoint -= 0x10000;
                charBuffer[charIndex++] = (char) (0xD800 | (codePoint >> 10));
                charBuffer[charIndex++] = (char) (0xDC00 | (codePoint & 0x3FF));
            } else {
                throw new IllegalArgumentException("Invalid Unicode code point: " + codePoint);
            }

            byteIndex += numBytes;
        }

        return new String(charBuffer, 0, charIndex);
    }
