    if (event == null)
        return;

    synchronized (this) {
        // if the buffer is full, remove the oldest event (index 0)
        if (eventBuffer.length == maxBackupIndex + 1) {
            // shift all elements to the left by one
            System.arraycopy(eventBuffer, 1, eventBuffer, 0, eventBuffer.length - 1);
        }
        // add the new event at the last position
        int pos = (eventCount < eventBuffer.length) ? eventCount : eventBuffer.length - 1;
        if (pos < eventBuffer.length) {
            eventBuffer[pos] = event;
            this.eventCount++;
