    public final MatchResult match(CharSequence uri) {
        if (uri == null || uri.length() == 0) {
            return null;
        }

        // Convert the URI to a string for easier manipulation
        String uriString = uri.toString();

        // Split the pattern into segments
        String[] patternSegments = pattern.split("/");
        String[] uriSegments = uriString.split("/");

        // Check if the number of segments matches
        if (patternSegments.length != uriSegments.length) {
            return null;
        }

        Map<String, String> variables = new HashMap<>();

        for (int i = 0; i < patternSegments.length; i++) {
            String patternSegment = patternSegments[i];
            String uriSegment = uriSegments[i];

            // Check if the pattern segment is a variable
            if (patternSegment.startsWith("{") && patternSegment.endsWith("}")) {
                String varName = patternSegment.substring(1, patternSegment.length() - 1);
                variables.put(varName, uriSegment);
            } else {
                // Static segment: check if it matches
                if (!patternSegment.equals(uriSegment)) {
                    return null;
                }
            }
        }

        return new MatchResult(variables);
    }
