@Override
public boolean containsKey(final Object key) {
    if (key == null) {
        throw new NullPointerException("Key cannot be null");
    }

    SectorNode node = root;
    while (node != null) {
        if (node.key.equals(key)) {
            return true;
        }
        if (key instanceof String) {
            String strKey = (String) key;
            String sectorKey = (String) node.key;
            int compareTo = strKey.compareTo(sectorKey);
            if (compareTo < 0) {
                node = node.left;
            } else if (compareTo > 0) {
                node = node.right;
            } else {
                return true;
            }
        } else {
            return false;
        }
    }
    return false;
}
