protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    // Build a map of adjacency lists based on the edges in the tour
    Map<V, Set<E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        adjacency.computeIfAbsent(source, k -> new HashSet<>()).add(edge);
        adjacency.computeIfAbsent(target, k -> new HashSet<>()).add(edge);
    }

    // Start from any vertex in the first edge
    V start = graph.getEdgeSource(tour.iterator().next());
    List<V> vertexPath = new ArrayList<>();
    List<E> edgePath = new ArrayList<>();

    V current = start;
    vertexPath.add(current);

    Set<E> usedEdges = new HashSet<>();
    while (usedEdges.size() < tour.size()) {
        boolean found = false;
        for (E edge : adjacency.get(current)) {
            if (!usedEdges.contains(edge)) {
                usedEdges.add(edge);
                edgePath.add(edge);

                V next = graph.getEdgeSource(edge).equals(current) ? graph.getEdgeTarget(edge) : graph.getEdgeSource(edge);
                vertexPath.add(next);

                current = next;
                found = true;
                break;
            }
        }
        if (!found) {
            throw new IllegalArgumentException("Invalid tour: not all edges can be traversed in a single path");
        }
    }

    return new GraphPathImpl<>(vertexPath, edgePath);
}
