protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    List<E> edges = new ArrayList<>(tour);
    edges.sort(Comparator.comparing(e -> graph.getTailVertex(e).toString()));
    List<V> vertices = new ArrayList<>();
    for (E e : edges) {
        V tail = graph.getTailVertex(e);
        if (vertices.isEmpty() || !vertices.get(vertices.size() - 1).equals(tail)) {
            V head = graph.getHeadVertex(e);
            if (vertices.isEmpty() || !vertices.get(vertices.size() - 1).equals(head)) {
                if (!vertices.isEmpty()) {
                    return new GraphPath<>(vertices, edges);
                }
            }
        }
    }
    return null;
}
