protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize an empty list to store the vertices in the tour
    List<V> vertices = new ArrayList<>();
    // Initialize a set to keep track of visited edges
    Set<E> usedEdges = new HashSet<>();
    // Find the start vertex (the first vertex in the graph that is incident to any edge in the tour)
    V start = null;
    for (E edge : tour) {
        if (start == null) {
            start = graph.getEdgeSource(edge);
        }
    }
    // If the tour is empty, return an empty path
    if (start == null) {
        return new GraphPathImpl<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }
    // Start the path from the first vertex
    vertices.add(start);
    V current = start;
    // Traverse the edges to build the tour path
    while (true) {
        boolean found = false;
        // Find an unused edge incident to the current vertex
        for (E edge : tour) {
            if (!usedEdges.contains(edge) && (graph.getEdgeSource(edge).equals(current) || graph.getEdgeTarget(edge).equals(current))) {
                found = true;
                // Determine the next vertex
                V next;
                if (graph.getEdgeSource(edge).equals(current)) {
                    next = graph.getEdgeTarget(edge);
                } else {
                    next = graph.getEdgeSource(edge);
                }
                // Mark the edge as used and move to the next vertex
                usedEdges.add(edge);
                vertices.add(next);
                current = next;
                break;
            }
        }
        // Stop if no unused edge is found
        if (!found) {
            break;
        }
    }
    // Create the result path
    return new GraphPathImpl<>(graph, vertices, new ArrayList<>(usedEdges), 0.0);
}
