protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        return new GraphPathImpl<>(new ArrayList<>(), new ArrayList<>());
    }

    // Build an adjacency list from the edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find the starting vertex (the one with a single edge or any available start)
    V currentVertex = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            currentVertex = entry.getKey();
            break;
        }
    }
    if (currentVertex == null) {
        // If no vertex with a single edge, start from any vertex
        currentVertex = adjacency.keySet().iterator().next();
    }

    List<V> vertexSequence = new ArrayList<>();
    List<E> edgeSequence = new ArrayList<>();
    vertexSequence.add(currentVertex);

    // Traverse the tour
    Set<E> usedEdges = new HashSet<>();
    while (vertexSequence.size() <= graph.getVertexCount()) {
        V nextVertex = null;
        E nextEdge = null;
        List<E> edges = adjacency.get(currentVertex);
        if (edges != null) {
            for (E edge : edges) {
                if (!usedEdges.contains(edge)) {
                    nextEdge = edge;
                    nextVertex = graph.getEdgeOpposite(edge, currentVertex);
                    break;
                }
            }
        }
        if (nextEdge == null || nextVertex == null) {
            break;
        }
        edgeSequence.add(nextEdge);
        usedEdges.add(nextEdge);
        vertexSequence.add(nextVertex);
        currentVertex = nextVertex;
    }

    return new GraphPathImpl<>(vertexSequence, edgeSequence);
}
