    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        // Find the start node
        Set<V> nodes = new HashSet<>(tour.size());
        for (E e : tour) {
            nodes.add(graph.getEndpoint(0, e));
            nodes.add(graph.getEndpoint(1, e));
        }

        // Find a node with degree 1 as start (if exists), otherwise pick any node
        V startPoint = null;
        for (V node : nodes) {
            if (graph.getDegree(node) == 1) {
                startPoint = node;
                break;
            }
        }
        if (startPoint == null) {
            startPoint = nodes.iterator().next();
        }

        // Build the tour by traversing edges
        List<V> path = new ArrayList<>(tour.size() + 1);
        List<E> pathEdges = new ArrayList<>(tour.size());
        Set<E> remainingEdges = new HashSet<>(tour);

        V current = startPoint;
        path.add(current);

        while (!remainingEdges.isEmpty()) {
            // Find an edge from current
            E nextEdge = null;
            for (E e : remainingEdges) {
                if (graph.getEndpoint(0, e).equals(current) || graph.getEndpoint(1, e).equals(current)) {
                    nextEdge = e;
                    break;
                }
            }

            if (nextEdge == null) {
                throw new IllegalArgumentException("Invalid tour: disconnected edges");
            }

            pathEdges.add(nextEdge);
            remainingEdges.remove(nextEdge);

            V other = graph.getEndpoint(0, nextEdge).equals(current) ? graph.getEndpoint(1, nextEdge) : graph.getEndpoint(0, nextEdge);
            path.add(other);
            current = other;
        }

        return new LengthBasedPath<>(graph, path, pathEdges);
    }
