public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    if (array1 == null && array2 == null) {
        return null;
    }
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }

    // Find the overlap: check if the end of array1 matches the beginning of array2
    int len1 = array1.length;
    int len2 = array2.length;
    int maxOverlap = Math.min(len1, len2);
    int overlap = 0;
    for (int i = maxOverlap; i >= 1; i--) {
        boolean match = true;
        for (int j = 0; j < i; j++) {
            if (!array1[len1 - i + j].equals(array2[j])) {
                match = false;
                break;
            }
        }
        if (match) {
            overlap = i;
            break;
        }
    }

    // Create the new array with total length = len1 + len2 - overlap
    int totalLength = len1 + len2 - overlap;
    String[] result = new String[totalLength];
    System.arraycopy(array1, 0, result, 0, len1);
    System.arraycopy(array2, overlap, result, len1, len2 - overlap);

    return result;
}
