    String[] result = new String[totalLength];

    if (array1 != null) {
        System.arraycopy(array1, 0, result, 0, length1);
    }

    if (array2 != null) {
        System.arraycopy(array2, 0, result, length1, length2);
        for (int i = 0; i < Math.min(length1, length2); i++) {
            result[length1 + length2 + i] = array1[i];
        }
    } else {
