        boolean foundCurrent = false;
        while (iterator.hasNext()) {
            V next = iterator.next();
            if (foundCurrent) {
                current = next;
                break;
            }
            if (next.equals(current)) {
                foundCurrent = true;
            }
        }
        if (!foundCurrent) {
            return null;
        }
        if (!iterator.hasNext()) {
            current = null;
        }
    }
    return current;
}
