public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int count = 0;
    for (int i = path.length() - 1; i >= 0; i--) {
        char character = path.charAt(i);
        if (character == '.') {
            count = i;
            break;
        }
        if (character == '/' || character == '\\') {
            return path;
        }
    }
    if (count > 0) {
        return path.substring(0, count);
    }
    return path;
}
