        totalSum += val;
    }
    // suffixSum[i] = totalSum - sum(bounds[0..i-1])
    // But it's simpler to compute from the end
    // Let's compute suffix sum array properly
    Long[] suffixArr = new Long[n + 1];
    for (int i = n; i >= 0; i--) {
        suffixArr[i] = 0L;
    }
    for (int i = n - 1; i >= 0; i--) {
        suffixArr[i] = suffixArr[i + 1] + bounds.get(i);
    }
    // Now build the result list of size n
    // suffixSumList[i] = suffixArr[i]
    for (int i = 0; i < n; i++) {
        suffixSumList.add(suffixArr[i]);
    }
    totalSum = suffixArr[0];
    return new Pair<>(suffixSumList, totalSum);
}
