public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Find the start of the current name component
    int end = nameStart;
    while (end < this.str.length() && Character.isLetter(this.str.charAt(end))) {
        end++;
    }
    if (end == nameStart) {
        return;
    }
    // Add the first letter of each word component
    buf.append(Character.toUpperCase(this.str.charAt(nameStart)));
    // If there are more characters, abbreviate the rest
    if (end > nameStart + 1) {
        int next = end;
        while (next < this.str.length() && Character.isLetter(this.str.charAt(next))) {
            next++;
        }
        if (next < this.str.length()) {
            // There might be more name components separated by non-letter characters
            for (int i = end; i < next; i++) {
                if (!Character.isLetter(this.str.charAt(i))) {
                    // Next component starts
                    int nextStart = i + 1;
                    int nextEnd = nextStart;
                    while (nextEnd < this.str.length() && Character.isLetter(this.str.charAt(nextEnd))) {
                        nextEnd++;
                    }
                    if (nextEnd > nextStart) {
                        if (buf.length() > 1) {
                            buf.append('.');
                        }
                        buf.append(Character.toUpperCase(this.str.charAt(nextStart)));
                    }
                    break;
                }
            }
        }
    }
}
