    for (K key : keys) {
        int index = Collections.binarySearch(keys, key);
        if (index >= 0) {
            index = lowerBound;
        } else {
            index = -index - 1;
            index = Math.min(index, 0);
            if (index > lowerBound) {
                index = lowerBound;
            }
        }
        lowerBounds.add((int) (1 - index) - 1);
        lowerBound = Math.max(lowerBound, 0) + 1;
    }
    return lowerBounds;
}
