public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path cannot be null");
    }

    // Split path into segments
    List<String> pathSegments = new ArrayList<>();
    String[] pathParts = path.split("/");
    for (String part : pathParts) {
        if (!part.isEmpty() && !part.equals(".")) {
            pathSegments.add(part);
        }
    }

    // Process relative path segments
    String[] relativeParts = relativePath.split("/");
    for (String relativePart : relativeParts) {
        if (relativePart.isEmpty() || relativePart.equals(".")) {
            continue;
        }
        if (relativePart.equals("..")) {
            if (!pathSegments.isEmpty()) {
                pathSegments.remove(pathSegments.size() - 1);
            }
        } else {
            pathSegments.add(relativePart);
        }
    }

    // Reconstruct the path
    String result = String.join("/", pathSegments);

    // Add leading slash if original path had one
    if (path.startsWith("/") && !result.startsWith("/")) {
        result = "/" + result;
    }

    return result;
}
