public static String applyRelativePath(String path,String relativePath){
    if (path == null) {
        path = "";
    }
    if (relativePath == null) {
        relativePath = "";
    }

    // Normalize the base path by ensuring it ends with a separator if not empty
    String normalizedPath = path;
    if (!normalizedPath.isEmpty() && !normalizedPath.endsWith("/")) {
        normalizedPath = normalizedPath + "/";
    }

    // Handle the relative path
    String result = normalizedPath + relativePath;

    // Resolve any ".." or "." components
    String[] parts = result.split("/");
    java.util.LinkedList<String> stack = new java.util.LinkedList<>();

    for (String part : parts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
        } else {
            stack.addLast(part);
        }
    }

    // If the resulting path is empty, return the root
    if (stack.isEmpty()) {
        return "/";
    }

    StringBuilder sb = new StringBuilder();
    boolean first = true;
    for (String s : stack) {
        if (first) {
            sb.append(s);
            first = false;
        } else {
            sb.append("/").append(s);
        }
    }

    return sb.toString();
