private String buildContentRange(){
    long totalSize = this.contentLength;
    long index = this.index;
    if (totalSize == -1) {
        return "bytes " + index + "-" + index;
    } else {
        return "bytes " + index + "-" + (index + 1) + "/" + totalSize;
    }
